<?php defined('BASEPATH') or exit('No direct script access allowed');$standalone_mode=true;$company_page_title='Tarefas avulsas';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_standalone_tasks'.$q);$labels=['todo'=>'A fazer','in_progress'=>'Em andamento','done'=>'Concluída'];$hidden=function($action)use($esc,$company_standalone_tasks_csrf,$request_key,$task){foreach(['action'=>$action,'company_standalone_tasks_csrf'=>$company_standalone_tasks_csrf,'request_key'=>$request_key] as $n=>$v)echo '<input type="hidden" name="'.$esc($n).'" value="'.$esc($v).'">';if($task)echo '<input type="hidden" name="task_id" value="'.(int)$task['id'].'"><input type="hidden" name="revision" value="'.(int)$task['revision'].'">';}; ?>
<section class="company-settings-card"><h1>Tarefas avulsas da empresa</h1><p>Tarefas sem projeto. Seu checklist, comentários e tempo pertencem exclusivamente a esta empresa.</p><?php if($error){ ?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><?php } ?>
<?php if($task){ ?><?php if($can_create){ ?><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_task_copies?kind=standalone&source='.(int)$task['id'])); ?>">Revisar nova cópia privada desta tarefa</a></p><?php }else{ ?><p>Copiar uma tarefa exige permissão atual para criar tarefas nesta empresa.</p><?php } ?><h2><?= $esc($task['name']); ?> — <?= $esc($labels[$task['status']]); ?></h2><p><?= nl2br($esc($task['description'])); ?></p><p>Prazo <?= $esc($task['due_date']); ?></p><h3>Checklist</h3><ul><?php foreach($task['checklist'] as $item){ ?><li><?= $item['done']?'Concluído: ':'Pendente: '; ?><?= $esc($item['text']); ?></li><?php } ?></ul><h3>Comentários</h3><?php foreach($task['comments'] as $comment){ ?><article><p><?= nl2br($esc($comment['body'])); ?></p><small><?= $esc($comment['created_at']); ?> · Funcionário #<?= (int)$comment['actor_id']; ?></small></article><?php } ?><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_standalone_billing?task='.(int)$task['id'])); ?>">Revisar faturamento da tarefa avulsa</a></p><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_time_batches?kind=standalone')); ?>">Selecionar timers encerrados para faturamento parcial</a></p><h3>Tempo registrado</h3><ul><?php $running=false;foreach($task['timers'] as $timer){if((int)$timer['actor_id']===$actor&&$timer['stopped_at']===null)$running=true; ?><li>Funcionário #<?= (int)$timer['actor_id']; ?> · <?= $esc($timer['started_at']); ?> · <?= $timer['stopped_at']===null?'Em execução':(int)$timer['seconds'].' segundos'; ?></li><?php } ?></ul>
<?php if($can_edit&&$task['status']!=='done'){ ?><?= form_open($url());$hidden('comment'); ?><label for="task-comment">Adicionar comentário</label><textarea id="task-comment" name="comment" class="form-control" maxlength="4000" required></textarea><button type="submit">Registrar comentário</button><?= form_close(); ?><?= form_open($url());$hidden($running?'stop':'start'); ?><p>Um cronômetro pode ficar ativo por funcionário, incluindo tarefas vinculadas a projetos. Nenhuma cobrança é gerada.</p><button type="submit"><?= $running?'Parar meu cronômetro':'Iniciar meu cronômetro'; ?></button><?= form_close(); ?><?php } ?>
<?php if($can_edit&&!in_array($task['billing_state']??'none',['converting','converted'],true)){ ?><h3>Editar tarefa</h3><?= form_open($url());$hidden('update'); ?><?php $values=$task;$form_id='task-edit';require APPPATH.'views/admin/companies/tasks_fields.php'; ?><label for="task-status">Estado</label><select id="task-status" name="task[status]" class="form-control"><?php foreach($labels as $v=>$label){ ?><option value="<?= $esc($v); ?>" <?= $v===$task['status']?'selected':''; ?>><?= $esc($label); ?></option><?php } ?></select><button type="submit">Salvar tarefa</button><?= form_close(); ?><?php } ?><?php } ?>
<h2>Lista da empresa</h2><table class="table"><thead><tr><th>Tarefa</th><th>Prazo</th><th>Estado</th></tr></thead><tbody><?php foreach($directory['items'] as $row){ ?><tr><td><a href="<?= $esc($url('?task='.(int)$row['id'])); ?>"><?= $esc($row['name']); ?></a></td><td><?= $esc($row['due_date']); ?></td><td><?= $esc($labels[$row['status']]); ?></td></tr><?php } ?></tbody></table><?php if($directory['next']!==null){ ?><a href="<?= $esc($url('?after='.$directory['next'])); ?>">Próxima página</a><?php } ?>
<?php if($can_create){ ?><h2>Nova tarefa avulsa</h2><?= form_open($url());$hidden('create'); ?><?php $values=['name'=>'','description'=>'','assignee_id'=>$actor,'due_date'=>date('Y-m-d'),'checklist'=>[]];$form_id='task-new';require APPPATH.'views/admin/companies/tasks_fields.php'; ?><button type="submit">Criar tarefa avulsa</button><?= form_close(); ?><?php } ?></section><?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
